async function runFlow(api) {
  const created = await api.post('/orders', { sku: 'A1', qty: 2 });
  if (created.status !== 201) return { ok: false, step: 'create' };
  const id = created.json.id;
  const read = await api.get(`/orders/${id}`);
  if (read.status !== 200 || read.json.qty !== 2) return { ok: false, step: 'read' };
  return { ok: true, id };
}

