function checkResponse(res) {
  const failures = [];
  if (res.status !== 200) failures.push('status');
  const ct = (res.headers && res.headers['content-type']) || '';
  if (!ct.startsWith('application/json')) failures.push('content-type');
  if (!res.body || typeof res.body.id !== 'string' || res.body.id === '') failures.push('id');
  return failures;
}
